  1	package com.loja.repositories.impl;
  2	
  3	import com.loja.domain.entities.*;
  4	import com.loja.infrastructure.Database;
  5	import com.loja.repositories.OrderRepository;
  6	
  7	import java.sql.*;
  8	import java.time.Instant;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	
 12	public class OrderRepositoryImpl implements OrderRepository {
 13	    private final Database database;
 14	
 15	    public OrderRepositoryImpl(Database database) {
 16	        this.database = database;
 17	    }
 18	
 19	    @Override
 20	    public void save(Order order) {
 21	        String orderSql = """
 22	            INSERT INTO orders (
 23	                id, customer_cpf, customer_email, status, created_at,
 24	                products_subtotal, coupon_discount, shipping_cost, delivery_days, insurance,
 25	                payment_adjustment, final_total, installments, installment_amount,
 26	                next_purchase_credit, gift
 27	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 28	        """;
 29	
 30	        String itemSql = "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)";
 31	
 32	        try (Connection conn = database.getConnection()) {
 33	            conn.setAutoCommit(false);
 34	
 35	            try (PreparedStatement orderStmt = conn.prepareStatement(orderSql);
 36	                 PreparedStatement itemStmt = conn.prepareStatement(itemSql)) {
 37	
 38	                OrderSummary summary = order.getSummary();
 39	
 40	                orderStmt.setString(1, order.getId());
 41	                orderStmt.setString(2, order.getCustomerCpf());
 42	                orderStmt.setString(3, order.getCustomerEmail());
 43	                orderStmt.setString(4, order.getStatus().name());
 44	                orderStmt.setTimestamp(5, Timestamp.from(order.getCreatedAt()));
 45	                orderStmt.setDouble(6, summary.getProductsSubtotal().toDouble());
 46	                orderStmt.setDouble(7, summary.getCouponDiscount().toDouble());
 47	                orderStmt.setDouble(8, summary.getShippingCost().toDouble());
 48	                orderStmt.setInt(9, summary.getDeliveryDays());
 49	                orderStmt.setDouble(10, summary.getInsurance().toDouble());
 50	                orderStmt.setDouble(11, summary.getPaymentAdjustment().toDouble());
 51	                orderStmt.setDouble(12, summary.getFinalTotal().toDouble());
 52	                orderStmt.setInt(13, summary.getInstallments());
 53	                orderStmt.setDouble(14, summary.getInstallmentAmount().toDouble());
 54	                orderStmt.setDouble(15, summary.getNextPurchaseCredit().toDouble());
 55	                orderStmt.setBoolean(16, summary.isGift());
 56	                orderStmt.executeUpdate();
 57	
 58	                for (OrderItem item : order.getItems()) {
 59	                    itemStmt.setString(1, order.getId());
 60	                    itemStmt.setString(2, item.getSku());
 61	                    itemStmt.setInt(3, item.getQuantity());
 62	                    itemStmt.executeUpdate();
 63	                }
 64	
 65	                conn.commit();
 66	
 67	            } catch (SQLException e) {
 68	                conn.rollback();
 69	                throw e;
 70	            }
 71	
 72	        } catch (SQLException e) {
 73	            throw new RuntimeException("Failed to save order: " + order.getId(), e);
 74	        }
 75	    }
 76	
 77	    @Override
 78	    public Order findById(String id) {
 79	        String orderSql = "SELECT * FROM orders WHERE id = ?";
 80	        String itemsSql = "SELECT * FROM order_items WHERE order_id = ?";
 81	
 82	        try (Connection conn = database.getConnection();
 83	             PreparedStatement orderStmt = conn.prepareStatement(orderSql);
 84	             PreparedStatement itemsStmt = conn.prepareStatement(itemsSql)) {
 85	
 86	            orderStmt.setString(1, id);
 87	            ResultSet orderRs = orderStmt.executeQuery();
 88	
 89	            if (!orderRs.next()) {
 90	                return null;
 91	            }
 92	
 93	            itemsStmt.setString(1, id);
 94	            ResultSet itemsRs = itemsStmt.executeQuery();
 95	
 96	            List<OrderItem> items = new ArrayList<>();
 97	            while (itemsRs.next()) {
 98	                items.add(new OrderItem(
 99	                        itemsRs.getString("sku"),
100	                        itemsRs.getInt("quantity")
101	                ));
102	            }
103	
104	            OrderSummary summary = new OrderSummary(
105	                    Money.of(orderRs.getDouble("products_subtotal")),
106	                    Money.of(orderRs.getDouble("coupon_discount")),
107	                    Money.of(orderRs.getDouble("shipping_cost")),
108	                    orderRs.getInt("delivery_days"),
109	                    Money.of(orderRs.getDouble("insurance")),
110	                    Money.of(orderRs.getDouble("payment_adjustment")),
111	                    Money.of(orderRs.getDouble("final_total")),
112	                    orderRs.getInt("installments"),
113	                    Money.of(orderRs.getDouble("installment_amount")),
114	                    Money.of(orderRs.getDouble("next_purchase_credit")),
115	                    orderRs.getBoolean("gift")
116	            );
117	
118	            Timestamp paidAtTs = orderRs.getTimestamp("paid_at");
119	            Instant paidAt = paidAtTs != null ? paidAtTs.toInstant() : null;
120	
121	            return new Order(
122	                    orderRs.getString("id"),
123	                    orderRs.getString("customer_cpf"),
124	                    orderRs.getString("customer_email"),
125	                    items,
126	                    summary,
127	                    OrderStatus.valueOf(orderRs.getString("status")),
128	                    orderRs.getTimestamp("created_at").toInstant(),
129	                    orderRs.getString("tracking_code"),
130	                    orderRs.getString("payment_transaction_id"),
131	                    paidAt
132	            );
133	
134	        } catch (SQLException e) {
135	            throw new RuntimeException("Failed to find order: " + id, e);
136	        }
137	    }
138	
139	    @Override
140	    public void update(Order order) {
141	        String sql = """
142	            UPDATE orders SET
143	                status = ?,
144	                tracking_code = ?,
145	                payment_transaction_id = ?,
146	                paid_at = ?
147	            WHERE id = ?
148	        """;
149	
150	        try (Connection conn = database.getConnection();
151	             PreparedStatement stmt = conn.prepareStatement(sql)) {
152	
153	            stmt.setString(1, order.getStatus().name());
154	            stmt.setString(2, order.getTrackingCode());
155	            stmt.setString(3, order.getPaymentTransactionId());
156	
157	            if (order.getPaidAt() != null) {
158	                stmt.setTimestamp(4, Timestamp.from(order.getPaidAt()));
159	            } else {
160	                stmt.setNull(4, Types.TIMESTAMP);
161	            }
162	
163	            stmt.setString(5, order.getId());
164	            stmt.executeUpdate();
165	
