  3	import com.loja.domain.entities.Order;
  4	import com.loja.domain.entities.OrderItem;
  5	import com.loja.domain.entities.Product;
  6	import com.loja.domain.events.PaymentConfirmedEvent;
  7	import com.loja.repositories.ProductRepository;
  8	
  9	public class StockObserver implements PaymentConfirmedObserver {
 10	    private final ProductRepository productRepository;
 11	
 12	    public StockObserver(ProductRepository productRepository) {
 13	        this.productRepository = productRepository;
 14	    }
 15	
 16	    @Override
 17	    public void onPaymentConfirmed(PaymentConfirmedEvent event) throws Exception {
 18	        Order order = event.getOrder();
 19	
 20	        for (OrderItem item : order.getItems()) {
 21	            Product product = productRepository.findBySku(item.getSku());
 22	            if (!product.hasStock(item.getQuantity())) {
 23	                throw new InsufficientStockException("Insufficient stock for product " + item.getSku());
 24	            }
 25	        }
 26	
 27	        for (OrderItem item : order.getItems()) {
 28	            Product product = productRepository.findBySku(item.getSku());
 29	            product.decreaseStock(item.getQuantity());
 30	            productRepository.update(product);
 31	        }
 32	    }
 33	
 34	    public static class InsufficientStockException extends Exception {
 35	        public InsufficientStockException(String message) {
 36	            super(message);
 37	        }
 38	    }
 39	}

